def load_for(need):
    if not isinstance(need, str):
        raise TypeError('need must be a string')
    files = ['SKILL.md']
    if '术语' in need or '隐私' in need:
        files.append('references/terms.md')
        files.append('references/privacy-rules.md')
    if '模板' in need:
        files.append('assets/meeting-template.md')
    if '清洗' in need:
        files.append('scripts/clean-transcript.py')
    return files

